UPDATE voice_sessions
SET status = 'PROCESSING'
WHERE user_id = #{userId, jdbcType=CHAR}
  AND session_id = #{sessionId, jdbcType=CHAR}
  AND status IN ('LISTENING', 'SPEAKING')
  AND expires_at > #{now, jdbcType=TIMESTAMP}

UPDATE voice_sessions
SET status = 'SPEAKING',
    current_step = #{currentStep}
WHERE user_id = #{userId, jdbcType=CHAR}
  AND session_id = #{sessionId, jdbcType=CHAR}
  AND status = 'PROCESSING'

UPDATE voice_sessions
SET status = #{previousStatus}
WHERE user_id = #{userId, jdbcType=CHAR}
  AND session_id = #{sessionId, jdbcType=CHAR}
  AND status = 'PROCESSING'

UPDATE voice_sessions
SET transfer_id = #{transferId, jdbcType=CHAR}
WHERE user_id = #{userId, jdbcType=CHAR}
  AND session_id = #{sessionId, jdbcType=CHAR}
  AND (transfer_id IS NULL OR transfer_id = #{transferId, jdbcType=CHAR})

UPDATE voice_sessions
SET status = #{status},
    current_step = #{currentStep}
WHERE user_id = #{userId, jdbcType=CHAR}
  AND session_id = #{sessionId, jdbcType=CHAR}
  AND status NOT IN ('CLOSED', 'EXPIRED')

UPDATE voice_sessions
SET status = 'CLOSED',
    current_step = #{currentStep},
    ended_at = #{endedAt}
WHERE user_id = #{userId, jdbcType=CHAR}
  AND session_id = #{sessionId, jdbcType=CHAR}
  AND status NOT IN ('CLOSED', 'EXPIRED')

UPDATE voice_sessions
SET active_input_turn_id = #{inputTurnId, jdbcType=CHAR}
WHERE user_id = #{userId, jdbcType=CHAR}
  AND session_id = #{sessionId, jdbcType=CHAR}
  AND status = 'LISTENING'
  AND active_input_turn_id IS NULL
  AND active_ai_turn_id IS NULL
  AND expires_at > #{now, jdbcType=TIMESTAMP}

UPDATE voice_sessions
SET status = 'PROCESSING'
WHERE user_id = #{userId, jdbcType=CHAR}
  AND session_id = #{sessionId, jdbcType=CHAR}
  AND status = 'LISTENING'
  AND active_input_turn_id = #{inputTurnId, jdbcType=CHAR}
  AND active_ai_turn_id IS NULL
  AND lifecycle_generation = #{lifecycleGeneration}
  AND expires_at > #{now, jdbcType=TIMESTAMP}

UPDATE voice_sessions
SET status = 'SPEAKING',
    active_input_turn_id = NULL,
    active_ai_turn_id = #{aiTurnId, jdbcType=CHAR}
WHERE user_id = #{userId, jdbcType=CHAR}
  AND session_id = #{sessionId, jdbcType=CHAR}
  AND status = 'PROCESSING'
  AND active_input_turn_id = #{inputTurnId, jdbcType=CHAR}
  AND active_ai_turn_id IS NULL
  AND lifecycle_generation = #{lifecycleGeneration}
  AND expires_at > #{now, jdbcType=TIMESTAMP}

UPDATE voice_sessions
SET status = 'LISTENING',
    active_ai_turn_id = NULL,
    lifecycle_generation = lifecycle_generation + 1
WHERE user_id = #{userId, jdbcType=CHAR}
  AND session_id = #{sessionId, jdbcType=CHAR}
  AND status = 'SPEAKING'
  AND active_input_turn_id IS NULL
  AND active_ai_turn_id = #{aiTurnId, jdbcType=CHAR}
  AND lifecycle_generation = #{lifecycleGeneration}
  AND expires_at > #{now, jdbcType=TIMESTAMP}

UPDATE voice_sessions
SET status = 'LISTENING',
    active_input_turn_id = NULL,
    lifecycle_generation = lifecycle_generation + 1
WHERE user_id = #{userId, jdbcType=CHAR}
  AND session_id = #{sessionId, jdbcType=CHAR}
  AND status IN ('LISTENING', 'PROCESSING')
  AND active_input_turn_id = #{inputTurnId, jdbcType=CHAR}
  AND active_ai_turn_id IS NULL
  AND lifecycle_generation = #{lifecycleGeneration}
  AND expires_at > #{now, jdbcType=TIMESTAMP}
